class Solution {public:vector<string>solve(vector<vector<int>>moves,vector<int>targets){int n=targets.size();vector<vector<int>>reverse(n);vector<int>degree(n),state(n),q;for(int u=0;u<n;u++)if(!targets[u])for(int v=0;v<n;v++)if(moves[u][v]){degree[u]++;reverse[v].push_back(u);}for(int u=0;u<n;u++)if(targets[u]||!degree[u]){state[u]=2;q.push_back(u);}for(int i=0;i<(int)q.size();i++){int v=q[i];for(int u:reverse[v])if(!state[u]){if(state[v]==2){state[u]=1;q.push_back(u);}else if(--degree[u]==0){state[u]=2;q.push_back(u);}}}vector<string>out(n);for(int i=0;i<n;i++)out[i]=state[i]==1?"WIN":state[i]==2?"LOSE":"DRAW";return out;}};